CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, openid VARCHAR(128) NOT NULL UNIQUE, unionid VARCHAR(128), nickname VARCHAR(128), avatar_url VARCHAR(512), country VARCHAR(64), province VARCHAR(64), city VARCHAR(64), gender INT NOT NULL DEFAULT 0, status INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE wechat_sessions (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, code VARCHAR(128) NOT NULL UNIQUE, openid VARCHAR(128) NOT NULL, session_key VARCHAR(256) NOT NULL, expires_at DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE daily_steps (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, step_date DATE NOT NULL, step_count INT NOT NULL DEFAULT 0, raw_payload TEXT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uk_daily_steps_user_date(user_id, step_date));
CREATE TABLE step_exchanges (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, exchange_date DATE NOT NULL, step_count INT NOT NULL DEFAULT 0, mileage INT NOT NULL DEFAULT 0, step_unit INT NOT NULL DEFAULT 100, mileage_unit INT NOT NULL DEFAULT 20, status INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uk_exchange_user_date(user_id, exchange_date));
CREATE TABLE route_nodes (id BIGINT PRIMARY KEY AUTO_INCREMENT, node_order INT NOT NULL UNIQUE, local_id VARCHAR(64) NOT NULL, city_name VARCHAR(128) NOT NULL UNIQUE, longitude DECIMAL(10,6) NOT NULL, latitude DECIMAL(10,6) NOT NULL, required_mileage INT NOT NULL, badge_code VARCHAR(64), city_image VARCHAR(512), city_detail TEXT, enabled INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE system_configs (id BIGINT PRIMARY KEY AUTO_INCREMENT, config_key VARCHAR(128) NOT NULL UNIQUE, config_value VARCHAR(256) NOT NULL, description VARCHAR(256), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
